\newcommand{\Div}{\operatorname{Div}}
\newcommand{\ZZ}{\mathbb{Z}}
\newcommand{\QQ}{\mathbb{Q}}
\newcommand{\RR}{\mathbb{R}}

\title{The Divisor Factorization of Torus-Knot OAM Spectra}
\author{Aristotle}
\date{\today}

\begin{document}

\begin{abstract}
A \emph{knotted light} beam is an optical field whose phase-singularity core traces
a knot $K$ in space. A physical conjecture links the quantized
orbital-angular-momentum (OAM) values such a beam may carry to the roots of the
Alexander polynomial $\Delta_K$ of that knot. For the family of $T(2,n)$ torus knots
the Alexander polynomial is the alternating geometric sum
$A_n(X) = 1 - X + X^2 - \cdots + X^{n-1}$. It was previously known that, for an odd
prime $p$, this polynomial coincides with a single cyclotomic polynomial,
$A_p = \Phi_{2p}$. We remove the primality hypothesis and establish the general
structural law: for every odd $n$, the $T(2,n)$ Alexander polynomial factors as the
product of the cyclotomic polynomials $\Phi_{2d}$ over the nontrivial divisors of
$n$,
\[
A_n(X) = \prod_{\substack{d \mid n \\ d > 1}} \Phi_{2d}(X).
\]
Consequently the OAM spectrum of a $T(2,n)$ beam is a disjoint union of
primitive-root layers, one layer of primitive $2d$-th roots of unity for each
nontrivial divisor $d \mid n$. We derive a master product identity
$\prod_{d \mid n}\Phi_{2d} = X^n + 1$ for odd $n$, the exact layer count
$\tau(n) - 1$, a primality criterion, a nested prime-power stratification
$A_{p^k} = \prod_{i=1}^{k}\Phi_{2p^i}$, and the channel count $n-1 =
\sum_{d\mid n,\,d>1}\varphi(2d)$.
\end{abstract}

\maketitle

\section{Introduction}

\subsection{Knotted light and its OAM spectrum}
Structured light fields can be engineered so that their optical vortices --- the
loci where the amplitude vanishes and the phase is undefined --- form linked and
knotted curves as the field propagates. These \emph{knotted light} configurations
realize genuine knots $K \subset \RR^3$ within a coherent beam. Such a beam also
carries \emph{orbital angular momentum}: the azimuthal winding of its phase
contributes quantized units of angular momentum along the propagation axis. A
physical conjecture ties these features together: the admissible OAM eigenvalues of
a knotted beam are governed by the roots of the Alexander polynomial $\Delta_K(X)$
of the knot $K$ traced by its vortex core. We determine that algebraic structure,
exactly and in full generality, for the $T(2,n)$ torus-knot family.

\subsection{The $T(2,n)$ family}
The torus knot $T(2,n)$ (for odd $n \ge 3$) wraps twice meridionally and $n$ times
longitudinally around a standard torus; $T(2,3)$ is the trefoil and $T(2,5)$ the
cinquefoil. Its Alexander polynomial (suitably normalized) is
\[
A_n(X) = \sum_{k=0}^{n-1} (-1)^k X^k = 1 - X + X^2 - \cdots + X^{\,n-1}.
\]
We treat $A_n \in \ZZ[X]$ for all odd $n \ge 1$. Everything rests on one identity.

\begin{lemma}[Fundamental identity]\label{lem:fund}
For all $n$, $\; A_n(X)\,(X+1) = X^n + 1$ (using that $n$ is odd for the sign).
\end{lemma}
\begin{proof}
Multiplying the alternating sum by $X+1$ telescopes: all interior terms cancel,
leaving $(-1)^{n-1}X^n + 1$, which equals $X^n + 1$ for odd $n$.
\end{proof}

\subsection{Cyclotomic polynomials}
For $m \ge 1$, the $m$-th cyclotomic polynomial $\Phi_m(X)\in\ZZ[X]$ is the monic
polynomial whose roots are exactly the primitive $m$-th roots of unity. We use
\begin{equation}\label{eq:cyc}
X^m - 1 = \prod_{d \mid m} \Phi_d(X),
\end{equation}
that each $\Phi_m$ is irreducible over $\QQ$ (a single Galois orbit), and
$\deg\Phi_m = \varphi(m)$. Note $\Phi_2 = X+1$ and $\Phi_6 = X^2 - X + 1$.

\section{Divisor combinatorics for $2n$ with $n$ odd}

\begin{lemma}[Odd divisors]\label{lem:odd}
If $n$ is odd and $d \mid n$, then $d$ is odd.
\end{lemma}
\begin{proof}
An even divisor $d$ would give $2 \mid d \mid n$, contradicting $n$ odd.
\end{proof}

\begin{lemma}[Divisor split]\label{lem:split}
For every $n \ge 1$, $\; \Div(2n) = \Div(n) \cup \{\,2d : d \in \Div(n)\,\}$.
\end{lemma}
\begin{proof}
Since $\Div(2) = \{1,2\}$, every divisor of $2n$ is $1\cdot d$ or $2\cdot d$ with
$d \mid n$, and conversely all such products divide $2n$.
\end{proof}

\begin{lemma}[Disjointness]\label{lem:disj}
If $n$ is odd, then $\Div(n)$ and $\{2d : d \mid n\}$ are disjoint, and
$d \mapsto 2d$ is injective.
\end{lemma}
\begin{proof}
Every $2d$ is even while, by Lemma~\ref{lem:odd}, every $d \mid n$ is odd;
injectivity of doubling is clear.
\end{proof}

\section{The master product identity}

\begin{theorem}[Master identity]\label{thm:master}
For odd $n > 0$, $\;\displaystyle \prod_{d \mid n} \Phi_{2d}(X) = X^n + 1.$
\end{theorem}
\begin{proof}
Work in $R = \ZZ[X]$. By \eqref{eq:cyc} at $2n$ and $n$,
$\prod_{e \mid 2n}\Phi_e = X^{2n}-1$ and $\prod_{d\mid n}\Phi_d = X^n - 1$. By
Lemmas~\ref{lem:split}--\ref{lem:disj},
\[
X^{2n}-1 = \prod_{e\mid 2n}\Phi_e
= \Big(\prod_{d\mid n}\Phi_d\Big)\Big(\prod_{d\mid n}\Phi_{2d}\Big)
= (X^n-1)\prod_{d\mid n}\Phi_{2d}.
\]
Since $X^{2n}-1 = (X^n-1)(X^n+1)$ and $X^n - 1 \ne 0$ in the domain $R$, cancelling
gives $\prod_{d\mid n}\Phi_{2d} = X^n + 1$.
\end{proof}

\section{The divisor factorization of $A_n$}

\begin{theorem}[Divisor factorization]\label{thm:main}
For every odd $n > 0$,
\[
A_n(X) = \prod_{\substack{d \mid n \\ d > 1}} \Phi_{2d}(X).
\]
\end{theorem}
\begin{proof}
Let $P = \prod_{d\mid n,\,d>1}\Phi_{2d}$. The only divisor of $n$ not exceeding $1$
is $d=1$, and $\Phi_{2} = X+1$. Hence by Theorem~\ref{thm:master},
\[
P\,(X+1) = \Big(\prod_{\substack{d\mid n\\ d>1}}\Phi_{2d}\Big)\Phi_2
= \prod_{d\mid n}\Phi_{2d} = X^n + 1.
\]
Comparing with Lemma~\ref{lem:fund}, $A_n(X)(X+1) = X^n+1 = P\,(X+1)$; cancelling
the nonzero $X+1$ yields $A_n = P$.
\end{proof}

\begin{remark}
The roots of $A_n$ are exactly the union, over nontrivial divisors $d \mid n$, of
the primitive $2d$-th roots of unity: all on the unit circle, none spurious. The
OAM spectrum of a $T(2,n)$ beam is thus a disjoint union of irreducible
primitive-root layers indexed by the nontrivial divisor lattice of $n$.
\end{remark}

\section{Structural corollaries}

\begin{corollary}[Layer count]\label{cor:count}
For $n > 0$, $\;\#\{d \mid n : d > 1\} = \tau(n) - 1$.
\end{corollary}
\begin{proof}
The set is $\Div(n)\setminus\{1\}$ and $1 \in \Div(n)$.
\end{proof}

\begin{corollary}[Primality criterion]\label{cor:prime}
For $n \ge 2$, the spectrum has exactly one layer iff $n$ is prime.
\end{corollary}
\begin{proof}
By Corollary~\ref{cor:count} the count is $\tau(n)-1$, equal to $1$ iff
$\tau(n) = 2$, i.e.\ iff $n$ is prime. In that case Theorem~\ref{thm:main} reduces
to $A_p = \Phi_{2p}$, recovering the prior prime-case identification.
\end{proof}

\begin{corollary}[Prime-power stratification]\label{cor:pp}
For an odd prime $p$ and $k \ge 0$,
$\; A_{p^k}(X) = \prod_{i=1}^{k} \Phi_{2p^i}(X)$ (empty product $=1$ when $k=0$).
\end{corollary}
\begin{proof}
The divisors of $p^k$ exceeding $1$ are $\{p^i : 1 \le i \le k\}$; substitute into
Theorem~\ref{thm:main} (valid as $p^k$ is odd) and re-index by $i$.
\end{proof}

\begin{corollary}[Channel count]\label{cor:deg}
For odd $n > 0$, $\;\deg A_n = n - 1$, equivalently
$\sum_{d\mid n,\,d>1}\varphi(2d) = n - 1$.
\end{corollary}
\begin{proof}
From Lemma~\ref{lem:fund}, $\deg(A_n(X+1)) = \deg(X^n+1) = n$; since $A_n$ has unit
leading term $X^{n-1}$ for odd $n$, $\deg A_n + 1 = n$. Summing degrees across
Theorem~\ref{thm:main} with $\deg\Phi_{2d} = \varphi(2d)$ gives the totient
identity.
\end{proof}

\section{Worked examples}

\begin{example}
$n=3$: layers $\{3\}$, $A_3 = \Phi_6 = X^2 - X + 1$, $2 = \varphi(6)$ channels.
$n=9$: layers $\{3,9\}$, $A_9 = \Phi_6\Phi_{18}$, $\deg = 2 + 6 = 8$.
$n=15$: layers $\{3,5,15\}$, $A_{15} = \Phi_6\Phi_{10}\Phi_{30}$,
$\deg = 2 + 4 + 8 = 14$. $n=27$: nested tower $\Phi_6\Phi_{18}\Phi_{54}$,
$2 + 6 + 18 = 26$.
\end{example}

\section{Discussion and future directions}
The stratification prescribes exactly which primitive roots of unity a $T(2,n)$
beam supports, a target spectrum for hologram synthesis; the primality criterion
turns a spectral count into an arithmetic test; and each layer, being an
irreducible cyclotomic factor, is a canonical intrinsic feature. Natural
continuations: (1) the unordered layer list $\{2d : d\mid n,\,d>1\}$ as a complete
Galois-orbit fingerprint of a beam within the $T(2,\cdot)$ family; (2) the
non-cyclotomic ``metallic'' exception of the figure-eight knot, whose
$X^2 - 3X + 1$ has reciprocal roots off the unit circle, contrasting with the
torus family at $b = 1$; (3) exact self-similarity of prime-power beams under
$p$-fold angular rescaling $\zeta \mapsto \zeta^p$.

\section{Conclusion}
For every odd $n$, $A_n = \prod_{d\mid n,\,d>1}\Phi_{2d}$. The OAM spectrum of a
$T(2,n)$ knotted-light beam is a disjoint union of primitive-root layers, one per
nontrivial divisor, with channel count $n-1$, layer count $\tau(n)-1$, and a single
layer precisely when $n$ is prime. The arithmetic of $n$ is written directly into
the geometry of the beam.

