from __future__ import annotations
from math import gcd
from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def euler_phi(n: int) -> int:
    return sum(1 for k in range(1, n + 1) if gcd(k, n) == 1)

def oam_stratification(n: int) -> List[dict]:
    """Return the OAM layers of a T(2,n) beam: one primitive-2d-root layer per
    nontrivial divisor d | n, with size phi(2d)."""
    layers = []
    for d in divisors(n):
        if d > 1:
            layers.append({"divisor": d, "modulus": 2 * d, "size": euler_phi(2 * d)})
    return layers

if __name__ == "__main__":
    for n in [3, 9, 15, 45, 105]:
        layers = oam_stratification(n)
        total = sum(L["size"] for L in layers)
        print(f"n={n}: {len(layers)} layers, {total} channels (= n-1 = {n-1})")
        for L in layers:
            dv, md, sz = L["divisor"], L["modulus"], L["size"]
            print(f"   divisor {dv:3d} -> primitive {md}-th roots, size phi({md})={sz}")

