from typing import List

def poly_mul(a: List[int], b: List[int]) -> List[int]:
    r = [0] * (len(a) + len(b) - 1)
    for i, ai in enumerate(a):
        for j, bj in enumerate(b):
            r[i + j] += ai * bj
    return r

def poly_divmod(num: List[int], den: List[int]) -> tuple[List[int], List[int]]:
    num = num[:]
    quo = [0] * max(1, len(num) - len(den) + 1)
    rem = num[:]
    while len(rem) >= len(den) and any(rem):
        k = len(rem) - len(den)
        c = rem[-1] // den[-1]
        quo[k] = c
        for i, d in enumerate(den):
            rem[k + i] -= c * d
        while len(rem) > 1 and rem[-1] == 0:
            rem.pop()
    return quo, rem

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def cyclotomic(m: int) -> List[int]:
    """m-th cyclotomic polynomial via Phi_m = (X^m - 1) / prod_{d|m, d<m} Phi_d."""
    xm = [-1] + [0] * (m - 1) + [1]
    denom: List[int] = [1]
    for d in divisors(m):
        if d < m:
            denom = poly_mul(denom, cyclotomic(d))
    quo, rem = poly_divmod(xm, denom)
    assert not any(rem)
    return quo

