from math import gcd
from typing import List, Dict

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def euler_phi(n: int) -> int:
    return sum(1 for k in range(1, n + 1) if gcd(k, n) == 1)

def stratify_spectrum(n: int) -> Dict[str, object]:
    """Compute the OAM stratification of a T(2,n) beam.
    Returns the layer moduli, their sizes, layer count tau(n)-1, and channel
    count n-1, and flags whether n is prime (single-layer)."""
    layers = [2 * d for d in divisors(n) if d > 1]
    sizes = [euler_phi(m) for m in layers]
    return {
        "layer_moduli": layers,
        "layer_sizes": sizes,
        "layer_count": len(layers),
        "channel_count": sum(sizes),
        "is_prime": len(layers) == 1 and n >= 2,
    }

