import matplotlib.pyplot as plt
from math import gcd
from typing import List

def divisors(n: int) -> List[int]:
    return [d for d in range(1, n + 1) if n % d == 0]

def euler_phi(n: int) -> int:
    return sum(1 for k in range(1, n + 1) if gcd(k, n) == 1)

def plot_channel_partition(nmax: int = 45) -> None:
    """Stacked-bar chart: for each odd n, show how the n-1 OAM channels partition
    into divisor-indexed layers of size phi(2d)."""
    ns = list(range(3, nmax + 1, 2))
    fig, ax = plt.subplots(figsize=(10, 5))
    for n in ns:
        bottom = 0
        for d in divisors(n):
            if d > 1:
                h = euler_phi(2 * d)
                ax.bar(n, h, bottom=bottom, width=1.4, edgecolor="k")
                bottom += h
    ax.set_xlabel("n (odd)")
    ax.set_ylabel("OAM channels (= n-1), partitioned into layers")
    ax.set_title("Divisor-stratified channel partition of T(2,n) spectra")
    plt.tight_layout()
    plt.savefig("channel_partition.png", dpi=150)

if __name__ == "__main__":
    plot_channel_partition()
